function updateWorkflowStages(text, stages) {
  const lines = text.split(`
`);
  if (!lines.length || lines[0].trim() !== "---") {
    throw new Error("Missing YAML frontmatter");
  }
  let fmEnd = null;
  for (let i = 1;i < lines.length; i++) {
    if (lines[i].trim() === "---") {
      fmEnd = i;
      break;
    }
  }
  if (fmEnd === null) {
    throw new Error("Unterminated YAML frontmatter");
  }
  let statesStart = null;
  let statesEnd = null;
  let statesIndent = 0;
  for (let i = 1;i < fmEnd; i++) {
    const stripped = lines[i].trimStart();
    if (stripped === "states:") {
      statesStart = i;
      statesIndent = lines[i].length - stripped.length;
      break;
    }
  }
  if (statesStart === null) {
    throw new Error("No states: block found in frontmatter");
  }
  for (let i = statesStart + 1;i < fmEnd; i++) {
    const stripped = lines[i].trimStart();
    if (!stripped)
      continue;
    const indent = lines[i].length - stripped.length;
    if (indent <= statesIndent) {
      statesEnd = i;
      break;
    }
  }
  if (statesEnd === null) {
    statesEnd = fmEnd;
  }
  const pad = " ".repeat(statesIndent + 2);
  const propPad = " ".repeat(statesIndent + 4);
  const newStatesLines = [lines[statesStart]];
  for (const stage of stages) {
    newStatesLines.push(`${pad}- name: ${stage.name}`);
    if (stage.initial)
      newStatesLines.push(`${propPad}initial: true`);
    if (stage.terminal)
      newStatesLines.push(`${propPad}terminal: true`);
    if (stage.gate)
      newStatesLines.push(`${propPad}gate: true`);
    if (stage.conditional)
      newStatesLines.push(`${propPad}conditional: true`);
    if (stage.feedback_to)
      newStatesLines.push(`${propPad}feedback-to: ${stage.feedback_to}`);
    if (!stage.worktree)
      newStatesLines.push(`${propPad}worktree: false`);
    if (stage.model)
      newStatesLines.push(`${propPad}model: ${stage.model}`);
  }
  const before = lines.slice(0, statesStart);
  const after = lines.slice(statesEnd);
  return [...before, ...newStatesLines, ...after].join(`
`);
}

// src/api.ts
function getEntityDetail(filepath) {
  const text = readFileSync2(filepath, "utf-8");
  const entity = parseEntity(text);
  return {
    ...entity,
    stage_reports: extractStageReports(text),
    filepath
  };
}
function updateScore(filepath, newScore) {
  const text = readFileSync2(filepath, "utf-8");
  const updated = updateEntityScore(text, newScore);
  writeFileSync(filepath, updated);
  const slug = basename2(filepath).replace(/\.md$/, "");
  captureEvent("score_updated", { slug, new_score: newScore });
}
function updateTags(filepath, tags) {
  const text = readFileSync2(filepath, "utf-8");
  const updated = updateEntityTags(text, tags);
  writeFileSync(filepath, updated);
  const slug = basename2(filepath).replace(/\.md$/, "");
  captureEvent("tags_updated", { slug, tag_count: tags.length });
}
function scanEntitiesDetailed(directory) {
  const glob = new Bun.Glob("*.md");
  const files = Array.from(glob.scanSync({ cwd: directory })).sort();
  const entities = [];
  for (const filename of files) {
    if (filename === "README.md")
      continue;
    const filepath = join3(directory, filename);
    const text = readFileSync2(filepath, "utf-8");
    const entity = parseEntity(text);
    entities.push({
      ...entity,
      stage_reports: extractStageReports(text),
      filepath,
      slug: filename.replace(/\.md$/, "")
    });
  }
  return entities;
}
function filterEntities(directory, filters) {
  const entities = scanEntitiesDetailed(directory);
  return entities.filter((entity) => {
    const fm = entity.frontmatter;
    if (filters.status && fm.status !== filters.status)
      return false;
    if (filters.tag && !entity.tags.includes(filters.tag))
      return false;
    if (filters.min_score != null) {
      const scoreStr = fm.score ?? "";
      if (!scoreStr)
        return false;
      const score = parseFloat(scoreStr);
      if (isNaN(score) || score < filters.min_score)
        return false;
    }
    if (filters.max_score != null) {
      const scoreStr = fm.score ?? "";
      if (!scoreStr)
        return false;
      const score = parseFloat(scoreStr);
      if (isNaN(score) || score > filters.max_score)
        return false;
    }
    return true;
  });
}

