class EventBuffer {
  db;
  capacity;
  insertStmt;
  selectAllStmt;
  selectSinceStmt;
  countStmt;
  selectByEntityStmt;
  selectChannelMsgSinceStmt;
  selectChannelMsgSinceEntityStmt;
  constructor(db, capacity) {
    this.db = db;
    this.capacity = capacity;
    this.insertStmt = db.query("INSERT INTO events (type, entity, stage, agent, timestamp, detail) VALUES (?, ?, ?, ?, ?, ?)");
    this.selectAllStmt = db.query("SELECT * FROM events ORDER BY seq ASC");
    this.selectSinceStmt = db.query("SELECT * FROM events WHERE seq > ? ORDER BY seq ASC");
    this.countStmt = db.query("SELECT COUNT(*) as cnt FROM events");
    this.selectByEntityStmt = db.query("SELECT * FROM events WHERE entity = ? ORDER BY seq ASC");
    this.selectChannelMsgSinceStmt = db.query("SELECT * FROM events WHERE type = 'channel_message' AND seq > ? ORDER BY seq ASC");
    this.selectChannelMsgSinceEntityStmt = db.query("SELECT * FROM events WHERE type = 'channel_message' AND seq > ? AND entity = ? ORDER BY seq ASC");
  }
  push(event) {
    if (!VALID_EVENT_TYPES.has(event.type)) {
      throw new Error(`Invalid event type: ${event.type}`);
    }
    const result = this.insertStmt.run(event.type, event.entity, event.stage, event.agent, event.timestamp, event.detail ?? null);
    const seq = Number(result.lastInsertRowid);
    const { cnt } = this.countStmt.get();
    if (cnt > this.capacity) {
      const excess = cnt - this.capacity;
      this.db.query("DELETE FROM events WHERE seq IN (SELECT seq FROM events ORDER BY seq ASC LIMIT ?)").run(excess);
    }
    return { seq, event };
  }
  getSince(afterSeq) {
    const rows = this.selectSinceStmt.all(afterSeq);
    return rows.map(rowToSequencedEvent);
  }
  getAll() {
    const rows = this.selectAllStmt.all();
    return rows.map(rowToSequencedEvent);
  }
  getByEntity(entity) {
    const rows = this.selectByEntityStmt.all(entity);
    return rows.map(rowToSequencedEvent);
  }
  clear() {
    this.db.query("DELETE FROM events").run();
  }
  getChannelMessagesSince(afterSeq, entity) {
    if (entity !== undefined && entity !== "") {
      const rows2 = this.selectChannelMsgSinceEntityStmt.all(afterSeq, entity);
      return rows2.map(rowToSequencedEvent);
    }
    const rows = this.selectChannelMsgSinceStmt.all(afterSeq);
    return rows.map(rowToSequencedEvent);
  }
}
function rowToSequencedEvent(row) {
  return {
    seq: row.seq,
    event: {
      type: row.type,
      entity: row.entity,
      stage: row.stage,
      agent: row.agent,
      timestamp: row.timestamp,
      detail: row.detail ?? undefined
    }
  };
}

