// src/channel.ts
import { mkdirSync as mkdirSync2, writeFileSync as writeFileSync4, readFileSync as readFileSync5, unlinkSync, existsSync as existsSync4 } from "fs";
import { createHash, randomUUID } from "crypto";
import { join as join6 } from "path";
import { homedir } from "os";

// src/entity-resolver.ts
import { basename as basename3 } from "path";
function resolveEntity(slug, projectRoot, workflow) {
  const workflows = discoverWorkflows(projectRoot);
  const matches = [];
  for (const wf of workflows) {
    const data = aggregateWorkflow(wf.dir);
    if (!data)
      continue;
    if (workflow && data.name !== workflow)
      continue;
    for (const entity of data.entities) {
      const entitySlug = entity.slug || basename3(entity.path).replace(/\.md$/, "");
      if (entitySlug === slug) {
        matches.push(entity.path);
      }
    }
  }
  if (matches.length === 0) {
    throw new Error(`Entity not found: ${slug}`);
  }
  if (matches.length > 1) {
    const label = workflow ? ` in workflow "${workflow}"` : "";
    throw new Error(`Ambiguous entity slug: ${slug}${label} matches: ${matches.join(", ")}`);
  }
  return matches[0];
}

